import{_ as d,o as e,c as o,a5 as r}from"./chunks/framework.BEZBAInb.js";const _=JSON.parse('{"title":"介紹","description":"","frontmatter":{"title":"介紹","order":1},"headers":[],"relativePath":"tc/latest/web-tool/guide.md","filePath":"tc/latest/web-tool/guide.md","lastUpdated":1788455378000}'),a={name:"tc/latest/web-tool/guide.md"};function l(i,t,c,s,h,n){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="konado-webtool" tabindex="-1">Konado WebTool <a class="header-anchor" href="#konado-webtool" aria-label="Permalink to &quot;Konado WebTool&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>Konado WebTool 是一個為 Konado 專案提供 Web 平台開發工具支援的插件。由於 Godot 4.x 在 Web 平台上預設會捕獲並禁用所有鍵盤快捷鍵，導致瀏覽器開發者工具快捷鍵（如 F12、F5 等）無法正常使用。這個插件專門解決此問題，允許在 Web 平台上使用常見的瀏覽器開發者工具快捷鍵，方便開發者在 Web 環境中進行除錯與開發。</p><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>Konado WebTool 透過在 Web 平台上注入 JavaScript 程式碼來實現快捷鍵放行。它會：</p><ol><li>檢測目前平台是否為 Web 平台</li><li>如果是 Web 平台且啟用了開發者工具支援，則注入快捷鍵處理程式碼</li><li>根據設定動態建構允許的快捷鍵列表</li><li>監聽鍵盤事件，阻止允許的快捷鍵繼續傳遞給 Godot，同時保留瀏覽器的預設行為</li></ol><h3 id="與其他解決方案比較" tabindex="-1">與其他解決方案比較 <a class="header-anchor" href="#與其他解決方案比較" aria-label="Permalink to &quot;與其他解決方案比較&quot;">​</a></h3><table tabindex="0"><thead><tr><th>解決方案</th><th>優勢</th><th>劣勢</th></tr></thead><tbody><tr><td>Konado WebTool</td><td>簡單易用、可設定性強、維護性好</td><td>無明顯劣勢</td></tr><tr><td>手動修改匯出範本</td><td>完全控制</td><td>技術要求高，需頻繁更新</td></tr><tr><td>開發環境切換</td><td>可在桌面平台除錯</td><td>無法捕捉 Web 平台特有問題</td></tr></tbody></table><h2 id="支援的瀏覽器快捷鍵" tabindex="-1">支援的瀏覽器快捷鍵 <a class="header-anchor" href="#支援的瀏覽器快捷鍵" aria-label="Permalink to &quot;支援的瀏覽器快捷鍵&quot;">​</a></h2><p>這些快捷鍵規範基於主流瀏覽器（如 Chrome、Firefox、Edge 等）的開發者工具標準快捷鍵，並參考各瀏覽器官方文件：</p><ul><li><a href="https://developer.mozilla.org/en-US/docs/Tools/Keyboard_shortcuts" target="_blank" rel="noreferrer">Firefox DevTools</a></li><li><a href="https://learn.microsoft.com/en-us/microsoft-edge/devtools-guide-chromium/shortcuts/" target="_blank" rel="noreferrer">Edge DevTools</a></li><li><a href="https://developer.chrome.com/docs/devtools/shortcuts/" target="_blank" rel="noreferrer">Chrome DevTools</a></li><li><a href="https://webkit.org/web-inspector/keyboard-shortcuts/" target="_blank" rel="noreferrer">Safari DevTools（WebKit）</a></li></ul><table tabindex="0"><thead><tr><th>快捷鍵</th><th>功能</th><th>啟用選項</th></tr></thead><tbody><tr><td>F12</td><td>開啟開發者工具</td><td><code>enable_f12</code></td></tr><tr><td>F5</td><td>重新整理頁面</td><td><code>enable_f5</code></td></tr><tr><td>F11</td><td>全螢幕切換</td><td><code>enable_f11</code></td></tr><tr><td>Ctrl+Shift+I (Win/Linux) / Cmd+Opt+I (Mac)</td><td>開啟元素面板</td><td><code>enable_ctrl_shift_i</code></td></tr><tr><td>Ctrl+Shift+J (Win/Linux) / Cmd+Opt+J (Mac)</td><td>開啟控制台</td><td><code>enable_ctrl_shift_j</code></td></tr><tr><td>Ctrl+Shift+C (Win/Linux) / Cmd+Shift+C (Mac)</td><td>檢查元素模式</td><td><code>enable_ctrl_shift_c</code></td></tr><tr><td>Ctrl+U (Win/Linux) / Cmd+U (Mac)</td><td>查看頁面原始碼</td><td><code>enable_ctrl_u</code></td></tr><tr><td>Ctrl+R (Win/Linux) / Cmd+R (Mac)</td><td>重新整理頁面</td><td><code>enable_ctrl_r</code></td></tr></tbody></table><h2 id="設定選項" tabindex="-1">設定選項 <a class="header-anchor" href="#設定選項" aria-label="Permalink to &quot;設定選項&quot;">​</a></h2><p>在自動載入的 <code>KonadoWebTool</code> 節點中，您可以透過以下屬性進行設定：</p><table tabindex="0"><thead><tr><th>屬性</th><th>類型</th><th>預設值</th><th>描述</th></tr></thead><tbody><tr><td><code>developer_shortcuts_enabled</code></td><td>bool</td><td>true</td><td>是否啟用 Web 開發者工具快捷鍵放行</td></tr><tr><td><code>allow_in_release</code></td><td>bool</td><td>false</td><td>是否在正式匯出套件中啟用快捷鍵放行</td></tr><tr><td><code>enable_f12</code></td><td>bool</td><td>true</td><td>是否啟用 F12 快捷鍵</td></tr><tr><td><code>enable_f5</code></td><td>bool</td><td>true</td><td>是否啟用 F5 快捷鍵</td></tr><tr><td><code>enable_f11</code></td><td>bool</td><td>true</td><td>是否啟用 F11 快捷鍵</td></tr><tr><td><code>enable_ctrl_shift_i</code></td><td>bool</td><td>true</td><td>是否啟用 Ctrl+Shift+I 快捷鍵</td></tr><tr><td><code>enable_ctrl_shift_j</code></td><td>bool</td><td>true</td><td>是否啟用 Ctrl+Shift+J 快捷鍵</td></tr><tr><td><code>enable_ctrl_shift_c</code></td><td>bool</td><td>true</td><td>是否啟用 Ctrl+Shift+C 快捷鍵</td></tr><tr><td><code>enable_ctrl_u</code></td><td>bool</td><td>true</td><td>是否啟用 Ctrl+U 快捷鍵</td></tr><tr><td><code>enable_ctrl_r</code></td><td>bool</td><td>true</td><td>是否啟用 Ctrl+R 快捷鍵</td></tr></tbody></table><p>為避免在正式環境暴露除錯入口，正式匯出套件預設不會安裝快捷鍵處理器。如需在執行階段修改設定，請在修改屬性後呼叫：</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">KonadoWebTool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">refresh_shortcuts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div>',17)])])}const p=d(a,[["render",l]]);export{_ as __pageData,p as default};
